fn ordering()->&'static Mutex<()>{static ORDER:OnceLock<Mutex<()>>=OnceLock::new();ORDER.get_or_init(||Mutex::new(()))}
fn remove_inner(state:&Mutex<Analyses>,order:&Mutex<()>,payload:Option<Value>,require_ready:bool,mut emit:impl FnMut(Value)->Result<(),String>)->Result<Value,String>{let input=payload.ok_or("Checksums are required")?;let values=input.as_array().ok_or("Checksums must be an array")?;if values.len()>64{return Err("Too many checksums".into())}let checksums=values.iter().map(|v|v.as_str().filter(|s|s.len()<=512).ok_or("Invalid checksum")).collect::<Result<Vec<_>,_>>()?;csdm_analysis_service::ordered(state,order,|guard|{if require_ready&&!READY.load(Ordering::SeqCst){return Err("Owned queue is no longer active".into())}guard.remove(&checksums);Ok(((),Some(json!({"name":"demos-removed-from-analyses","payload":input}))))},&mut emit)?;Ok(Value::Null)}
