fn abandon(state:&Mutex<Analyses>,order:&Mutex<()>,mut emit:impl FnMut(Value)->Result<(),String>)->Result<(),String>{csdm_analysis_service::ordered(state,order,|s|{let checksums:Vec<Value>=s.all().into_iter().map(|v|v["demoChecksum"].clone()).collect();s.clear();let event=if checksums.is_empty(){None}else{Some(json!({"name":"demos-removed-from-analyses","payload":checksums}))};Ok(((),event))},&mut emit)}
pub(super) fn stop_queue(state:&Mutex<Analyses>,order:&Mutex<()>,reason:String,emit:impl FnMut(Value)->Result<(),String>)->String{match abandon(state,order,emit){Ok(())=>reason,Err(e)=>format!("{reason}; queue cleanup or removal delivery unconfirmed: {e}")}}
fn outcome_summary(value:&Outcome)->&'static str{match value{Outcome::Inserted(_)=>"inserted",Outcome::AnalyzerFailed(_)=>"analysis-failed",Outcome::CorruptedUnsupported=>"corrupted-unsupported",Outcome::InvalidClaim=>"invalid-claim",Outcome::DuplicateExecution=>"duplicate-execution",Outcome::StateUnavailable=>"state-unavailable",Outcome::ImportFailed{commit_may_have_occurred:true,..}|Outcome::DeliveryFailed{commit_may_have_occurred:true,..}=>"commit-possibly-occurred",Outcome::ImportFailed{..}=>"import-not-committed",Outcome::DeliveryFailed{..}=>"delivery-failed-before-import"}}
fn handle_worker_result(state:&Mutex<Analyses>,order:&Mutex<()>,fixture:Fixture,result:Outcome,mut emit:impl FnMut(Value)->Result<(),String>)->Result<(),String>{match result{Outcome::Inserted(_)=>Ok(()),Outcome::AnalyzerFailed(_) if matches!(fixture,Fixture::Pg61|Fixture::Pg70|Fixture::Pg71|Fixture::Pg72|Fixture::Pg74)=>Ok(()),Outcome::DuplicateExecution=>Err("Analysis execution is already running".into()),Outcome::InvalidClaim=>Err("Analysis claim was rejected; queue state retained".into()),Outcome::StateUnavailable=>Err("Analysis state unavailable; queue cleanup unconfirmed".into()),other=>Err(stop_queue(state,order,format!("Owned analysis stopped: {other:?}; database commit may have occurred"),&mut emit))}}
// Called only before any prepared worker starts. Every claimed ID is reconciled on
// setup failure; a removal between claims simply yields fewer prepared workers.
fn reconcile_unstarted(state:&Mutex<Analyses>,order:&Mutex<()>,ids:Vec<u64>,error:String,emit:&mut impl FnMut(Value)->Result<(),String>)->String{let mut details=Vec::new();for id in ids{if let Err(e)=csdm_analysis_service::preparation_failure(state,order,id,&error,emit){details.push(format!("worker {id} error delivery: {e}"));if let Err(cleanup)=csdm_analysis_service::finish(state,order,id){details.push(format!("worker {id} cleanup unconfirmed: {cleanup}"));}}}let reason=if details.is_empty(){error}else{format!("{error}; {}",details.join("; "))};stop_queue(state,order,reason,emit)}
fn prepare_claims<T>(state:&Mutex<Analyses>,order:&Mutex<()>,max:usize,emit:&mut impl FnMut(Value)->Result<(),String>,mut prepare:impl FnMut(&super::csdm_analysis::Claim)->Result<T,String>)->Result<Vec<(super::csdm_analysis::Claim,T)>,String>{let mut prepared=Vec::new();let mut ids=Vec::new();let outcome=(||->Result<(),String>{for _ in 0..max{let Some(claim)=csdm_analysis_service::claim_and_start(state,order,max,emit)? else{break};ids.push(claim.run_id);let value=prepare(&claim)?;prepared.push((claim,value));}Ok(())})();if let Err(error)=outcome{return Err(reconcile_unstarted(state,order,ids,error,emit))}Ok(prepared)}
